public class RateLimiter {
  private final int max; private final Map<String, Integer> hits = new HashMap<>();
  public RateLimiter(int max) { if (max <= 0) throw new IllegalArgumentException(); this.max = max; }
  public boolean allow(String key) {
    int n = hits.getOrDefault(key, 0);
    if (n >= max) return false;
    hits.put(key, n + 1);
    return true;
  }
  public void reset(String key) { hits.remove(key); }
}

